sys_script_include.script:
var TrainNowUtils = Class.create();
TrainNowUtils.prototype = {
    initialize: function() {
    },

	// Função para mostrar o que o aplicante não se inscreveu
	refQualTraining: function () {

		var trainings = [];
		var grTrainings = new GlideRecord("x_1812797_trainnow_training_schedule");
		grTrainings.query();

		while(grTrainings.next()){
			var grEnrolled = new GlideRecord("x_1812797_trainnow_training_enrollment");
			grEnrolled.addQuery("opened_by", gs.getUserID());
			grEnrolled.addQuery("training", grTrainings.sys_id);
			grEnrolled.query();
			if(!grEnrolled.next() || grEnrolled.getValue("state") == "4"){
                trainings.push(grTrainings.getUniqueValue());
            }
		}

		return "sys_idIN" + trainings.join(",");

	},

    type: 'TrainNowUtils'
};
